      "adminGeneric.postbackReadiness.route.title": "Postback Readiness",
      "adminGeneric.postbackReadiness.route.description": "A read-only preparation and handoff guide for canonical administrators; it does not expose sensitive connection details, send events, or change attribution or payouts.",
      "adminGeneric.postbackReadiness.intro.kicker": "Canonical admin guidance · read-only",
      "adminGeneric.postbackReadiness.intro.title": "Prepare postback work carefully without turning the Web into configuration or event intake",
